from subcommands import diff_mpplus


class TestDiffMpplusUnpinnedLatest(unittest.TestCase):
    def test_preserved_artifact_allowlist_covers_html_and_json(self):
        self.assertEqual(
            diff_mpplus.PRESERVED_CHANGE_LOG_ARTIFACTS,
            (diff_mpplus.UNPINNED_LATEST_HTML, diff_mpplus.UNPINNED_LATEST_JSON),
        )

    def test_zero_diffs_writes_empty_unpinned_latest_artifacts(self):
        """One test where there were two, the pair having asserted one fact twice.

        ``test_no_new_commits_writes_empty_unpinned_latest_artifacts`` stood beside this one
        until 2026-09-11, differing only in the value stubbed into ``_count_newer_commits`` --
        0 there, 2 here -- and asserting the identical ``generate_report`` call and the
        identical None.  That the two agreed was the evidence that the branch they were
        covering did no work of its own; ``run_unpinned_latest``'s docstring says the rest.
        With the count gone there is one path, so there is one test.
        """
        with (
            mock.patch.object(
                diff_mpplus, "_latest_release_entry", return_value={"new": "v1"}
            ),
            mock.patch.object(diff_mpplus, "_refuse_unstored_boundaries"),
            mock.patch.object(
                diff_mpplus,
                "generate_report",
                return_value=(0, "2026-05-13"),
            ) as generate_mock,
        ):
            result = diff_mpplus.run_unpinned_latest()

        self.assertIsNone(result)
        generate_mock.assert_called_once_with(
            "v1",
            "HEAD",
            diff_mpplus.UNPINNED_LATEST_HTML,
            write_when_empty=True,
        )

    def test_latest_release_entry_is_the_chain_end_and_needs_no_git(self):
        """The terminal entry is read off releases.json, which is what a shallow clone needs.

        Lint-shaped rather than example-based: it asserts a decidable property of the tracked
        file -- that it is one unbroken chain -- and that ``_latest_release_entry`` returns the
        end of it.  A second terminal entry would mean the file had stopped being a chain, and
        is what the function raises on.
        """
        with open(diff_mpplus.RELEASES_JSON, encoding="utf-8") as in_fp:
            releases = json.load(in_fp)["releases"]

        continued = {entry["old"] for entry in releases}
        started = {entry["new"] for entry in releases}
        terminal = [entry for entry in releases if entry["new"] not in continued]
        initial = [entry for entry in releases if entry["old"] not in started]

        self.assertEqual(
            len(terminal), 1, "releases.json must end in exactly one entry"
        )
        self.assertEqual(
            len(initial), 1, "releases.json must begin at exactly one entry"
        )
        self.assertEqual(diff_mpplus._latest_release_entry(), terminal[0])

    def test_legacy_history_never_reuses_a_named_release_output(self):
        with open(diff_mpplus.RELEASES_JSON, encoding="utf-8") as in_fp:
            releases = json.load(in_fp)["releases"]

        self.assertTrue(releases, "releases.json must name at least one release")
        for entry in releases:
            args = argparse.Namespace(
                check=False,
                all=False,
                old=entry["old"],
                new=entry["new"],
                legacy_history=True,
                output=None,
                archive=None,
                pin=None,
            )
            named_output = f"{diff_mpplus.CHANGE_LOG_DIR}/{entry['name']}.html"
            with mock.patch.object(diff_mpplus, "generate_report") as generate_mock:
                diff_mpplus.run_from_args(args)

            old_rev = f"legacy:{entry['old']}"
            new_rev = f"legacy:{entry['new']}"
            legacy_output = diff_mpplus.default_output_path(old_rev, new_rev)
            self.assertNotEqual(legacy_output, named_output)
            generate_mock.assert_called_once_with(old_rev, new_rev, legacy_output)


class _ReportAssets(HTMLParser):
    def __init__(self):
        super().__init__()
        self.assets = set()

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == "script" and "src" in attrs:
            self.assets.add(attrs["src"])
        elif tag == "link" and attrs.get("rel") == "stylesheet":
            self.assets.add(attrs["href"])


def test_registered_report_tree_declares_every_checked_artifact():
    releases = json.loads(Path(diff_mpplus.RELEASES_JSON).read_text(encoding="utf-8"))[
        "releases"
    ]
    assert releases, "releases.json must name at least one release"
    directory = Path(diff_mpplus.CHANGE_LOG_DIR)
    expected = {"index.html"}
    shared_base = (directory / "../../report.css").resolve()
    assert shared_base.is_file(), shared_base
    for name in [*(entry["name"] for entry in releases), "unpinned-latest"]:
        report = directory / f"{name}.html"
        serialized = directory / f"{name}.json"
        assert report.is_file() and serialized.is_file(), name
        assert report.stat().st_size and serialized.stat().st_size, name
        expected.update((report.name, serialized.name))
        assets = _ReportAssets()
        assets.feed(report.read_text(encoding="utf-8"))
        assert assets.assets, f"no shared assets declared by {report}"
        assert "../../report.css" in assets.assets, report
        for asset in assets.assets:
            if asset == "../../report.css":
                assert (report.parent / asset).resolve() == shared_base
                continue
            assert (
                Path(asset).name == asset
            ), f"unexpected nonlocal shared asset {asset!r}"
            assert (directory / asset).is_file(), asset
            expected.add(asset)
            if asset.endswith(".css"):
                css = (directory / asset).read_text(encoding="utf-8")
                fonts = re.findall(r'url\("([^\"]+\.woff2)"\)', css)
                assert fonts, f"no Hebrew font declared by {asset}"
                for font in fonts:
                    font_path = (directory / font).resolve()
                    assert font_path.is_relative_to(directory.resolve()), font
                    assert font_path.is_file(), font
                    expected.add(font)
    index_assets = _ReportAssets()
    index_assets.feed((directory / "index.html").read_text(encoding="utf-8"))
    assert index_assets.assets == {"../../report.css", "style.css"}
    checked = diff_mpplus.generated_artifact_names()
    assert len(checked) == len(set(checked)), "duplicate checked artifact"
    assert set(checked) == expected


def test_registered_outputs_match_real_regeneration():
    published = Path(diff_mpplus.CHANGE_LOG_DIR)
    before = {
        path: path.read_bytes() for path in published.rglob("*") if path.is_file()
    }
    base = published / "../../report.css"
    base_before = base.read_bytes()
    with tempfile.TemporaryDirectory(prefix="mam-real-release-test-") as generated:
        diff_mpplus.run_all(generated)
        assert not diff_mpplus._generated_artifact_problems(generated)
    assert base.read_bytes() == base_before
    assert {
        path: path.read_bytes() for path in published.rglob("*") if path.is_file()
    } == before


def test_standalone_release_reports_match_published_reports():
    """Compare every registered release's standalone package with its published report."""
    published = Path(diff_mpplus.CHANGE_LOG_DIR)
    releases = json.loads(Path(diff_mpplus.RELEASES_JSON).read_text(encoding="utf-8"))[
        "releases"
    ]
    assert releases, "releases.json must name at least one release"
    with tempfile.TemporaryDirectory(
        prefix="mam-standalone-release-test-"
    ) as generated:
        directory = Path(generated)
        for entry in releases:
            name = entry["name"]
            args = argparse.Namespace(
                check=False,
                all=False,
                old=entry["old"],
                new=entry["new"],
                legacy_history=False,
                output=str(directory / f"{name}.html"),
                archive=None,
                pin=None,
            )
            diff_mpplus.run_from_args(args)
            expected_html = (
                (published / f"{name}.html")
                .read_bytes()
                .replace(b'href="../../report.css"', b'href="report-assets/report.css"')
            )
            assert (directory / f"{name}.html").read_bytes() == expected_html
            for asset in (f"{name}.json", "style.css", "filter.js"):
                assert (directory / asset).read_bytes() == (
                    published / asset
                ).read_bytes()
            font = Path("woff2/Taamey_D.woff2")
            assert (directory / font).read_bytes() == (published / font).read_bytes()
            assert (directory / "report-assets" / "report.css").read_bytes() == (
                published / "../../report.css"
            ).read_bytes()


def test_check_conflict_guard_covers_every_declared_selector():
    module = ast.parse(inspect.getsource(diff_mpplus))
    argument_function = next(
        node
        for node in module.body
        if isinstance(node, ast.FunctionDef) and node.name == "add_arguments"
    )
    declared = set()
    for node in ast.walk(argument_function):
        if (
            isinstance(node, ast.Call)
            and isinstance(node.func, ast.Attribute)
            and node.func.attr == "add_argument"
        ):
            for argument in node.args:
                if (
                    isinstance(argument, ast.Constant)
                    and isinstance(argument.value, str)
                    and argument.value.startswith("--")
                ):
                    declared.add(argument.value[2:].replace("-", "_"))
    runner = next(
        node
        for node in module.body
        if isinstance(node, ast.FunctionDef) and node.name == "run_from_args"
    )
    guard = next(
        node
        for node in ast.walk(runner)
        if isinstance(node, ast.Assign)
        and any(
            isinstance(target, ast.Name) and target.id == "conflicting"
            for target in node.targets
        )
    )
    guarded = {
        node.attr
        for node in ast.walk(guard.value)
        if isinstance(node, ast.Attribute)
        and isinstance(node.value, ast.Name)
        and node.value.id == "args"
    }
    assert declared and guarded == declared - {"check"}


def test_check_source_keeps_generation_and_comparison_in_its_temporary_scope():
    function = ast.parse(inspect.getsource(diff_mpplus.check_all)).body[0]
    scopes = [node for node in function.body if isinstance(node, ast.With)]
    assert len(scopes) == 1
    scope = scopes[0]
    assert len(scope.items) == 1
    context = scope.items[0]
    assert isinstance(context.context_expr, ast.Call)
    assert (
        isinstance(context.context_expr.func, ast.Name)
        and context.context_expr.func.id == "TemporaryDirectory"
    )
    assert isinstance(context.optional_vars, ast.Name)
    directory = context.optional_vars.id
    calls = {
        node.func.id: node
        for node in ast.walk(scope)
        if isinstance(node, ast.Call)
        and isinstance(node.func, ast.Name)
        and node.func.id in {"run_all", "_generated_artifact_problems"}
    }
    assert set(calls) == {"run_all", "_generated_artifact_problems"}
    for call in calls.values():
        assert (
            len(call.args) == 1
            and isinstance(call.args[0], ast.Name)
            and call.args[0].id == directory
        )


